solution:
mod music {
  mod player {
    pub fn play_track(name: Str) {
      io.println(name);
    }
    pub fn pause() { }
  }

  mod library {
    pub fn add_song(name: Str) { }
  }

  pub use player::play_track as play;
  pub use player::pause;
  pub use library::add_song as library_add;
}

fn main() -> Int {
  use music;
  music.play("Bohemian Rhapsody");
  music.pause();
  music.library_add("New Song");
  return 0;
}
